<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>订阅泄露风险分析</title>
    <style>
        :root{--bg:#eef2f1;--ink:#17211f;--muted:#6d7977;--line:#d8dfdd;--paper:#fff;--soft:#f7f9f8;--teal:#087f72;--teal-soft:#e4f4f1;--navy:#1d302e;--red:#bf3c2f;--red-soft:#fff0ed}
        *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 Arial,"Microsoft YaHei",sans-serif}.shell{max-width:1580px;margin:auto;padding:22px 28px 40px}.top{display:flex;justify-content:space-between;gap:18px}.eyebrow{color:var(--teal);font-size:11px;font-weight:700;letter-spacing:.12em}.top h1{margin:5px 0 4px;font-size:25px}.top p{margin:0;color:var(--muted)}button,input,select{font:inherit}.actions{display:flex;gap:8px}.button{border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink);padding:8px 11px;cursor:pointer}.button.primary{border-color:var(--navy);background:var(--navy);color:#fff}.filters{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin-top:20px;padding:14px 15px;border:1px solid var(--line);background:var(--paper)}.filters label{display:grid;gap:4px;color:var(--muted);font-size:12px}.filters input,.filters select{width:145px;min-height:34px;padding:7px 8px;border:1px solid var(--line);border-radius:3px;background:#fff;color:var(--ink)}.filters .wide input{width:200px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;margin-top:13px;border:1px solid var(--line);background:var(--line)}.metric{min-height:88px;padding:13px 15px;background:var(--paper)}.metric span,.metric small{display:block;color:var(--muted);font-size:12px}.metric b{display:block;margin-top:6px;font-size:24px;line-height:1}.metric small{margin-top:5px;color:var(--red);font-size:11px}.workspace{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(390px,.75fr);gap:14px;margin-top:14px}.panel{min-width:0;border:1px solid var(--line);background:var(--paper)}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:16px}.panel-head p{margin:3px 0 0;color:var(--muted);font-size:12px}.tabs{display:flex;gap:2px;padding:9px 11px 0;border-bottom:1px solid var(--line);overflow:auto}.tab{padding:8px 10px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);white-space:nowrap;cursor:pointer}.tab.active{border-bottom-color:var(--teal);color:var(--teal);font-weight:700}.table-wrap{overflow:auto}.ranking-table,.logs{width:100%;border-collapse:collapse}.ranking-table{min-width:760px}.ranking-table th,.ranking-table td,.logs th,.logs td{padding:10px 11px;border-bottom:1px solid #edf0ef;text-align:left;vertical-align:middle}.ranking-table th,.logs th{background:var(--soft);color:var(--muted);font-size:11px;font-weight:700}.ranking-table tbody tr{cursor:pointer}.ranking-table tbody tr:hover,.ranking-table tbody tr.selected{background:#eff8f6}.account{display:flex;align-items:center;gap:8px;min-width:175px}.avatar{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--teal-soft);color:var(--teal);font-size:11px;font-weight:700}.account b,.account small,.linked-account b,.linked-account small{display:block}.account small,.subtle,.linked-account small{color:var(--muted);font-size:11px}.risk{font-weight:700}.risk.high{color:var(--red)}.risk.medium{color:#b06a0a}.risk.low{color:var(--teal)}.risk-bar{width:70px;height:5px;margin-top:4px;background:#e4eae8}.risk-bar i{display:block;height:100%;background:var(--red)}.chip{display:inline-block;padding:2px 5px;border:1px solid #efc7c1;border-radius:3px;background:var(--red-soft);color:var(--red);font-size:11px;white-space:nowrap}.detail{background:var(--navy);border-color:var(--navy);color:#edf6f3}.detail .panel-head{border-color:#38504c}.detail .panel-head p,.detail .muted{color:#a8bfba}.detail-body{padding:16px}.case-title{display:flex;justify-content:space-between;gap:12px}.case-title h3{margin:0;font-size:18px}.case-title p{margin:4px 0 0;color:#a8bfba;font-size:12px}.score{min-width:64px;padding:7px 9px;text-align:center;border:1px solid #75443f;background:#4e2c2b;color:#ffb6aa}.score b{display:block;font-size:22px}.score small{font-size:10px}.detail-section{margin-top:20px}.section-title{display:flex;justify-content:space-between;margin-bottom:8px;color:#d8e8e4;font-size:12px;font-weight:700}.section-title span{color:#91aaa5;font-weight:400}.linked-list{display:grid;gap:8px}.linked-account{padding:10px;background:#29413d;border:1px solid #38524d}.linked-account b{color:#f0faf7}.linked-account small{margin-top:3px;color:#a8bfba}.notice{margin-top:16px;padding:9px 10px;border-left:3px solid #e69a57;background:#2e403d;color:#d8e8e4;font-size:11px}.pager{display:flex;align-items:center;gap:8px;padding:11px 14px}.pager span{color:var(--muted);font-size:12px}.pager button:disabled{opacity:.45;cursor:not-allowed}.state{padding:28px 15px;color:var(--muted)}.raw{margin-top:14px}.raw .table-wrap{max-height:470px}.logs{min-width:980px;font-size:12px}.ua{max-width:330px;overflow-wrap:anywhere;font-family:Consolas,monospace;font-size:11px}.badge{display:inline-block;padding:2px 6px;border-radius:9px;background:var(--teal-soft);color:#06685f;font-size:11px}.badge.red{background:var(--red-soft);color:var(--red)}@media(max-width:1050px){.workspace{grid-template-columns:1fr}.summary{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.shell{padding:15px 12px 28px}.top{display:block}.actions{margin-top:12px}.filters>*{width:calc(50% - 6px)}.filters input,.filters select,.filters .wide input{width:100%}.summary{grid-template-columns:repeat(2,1fr)}.metric{min-height:77px;padding:10px}.metric b{font-size:21px}}
    </style>
</head>
<body>
<main class="shell">
    <header class="top"><div><div class="eyebrow">SECURITY / SUBSCRIPTION EXPOSURE</div><h1>订阅泄露风险分析</h1><p>通过共享线索定位同一订阅被多个陌生来源使用的账号</p></div><div class="actions"><button id="logout" class="button" type="button">退出</button><button id="refresh" class="button primary" type="button">刷新数据</button></div></header>
    <form id="filters" class="filters">
        <label>开始日期<input name="start" type="date"></label><label>结束日期<input name="end" type="date"></label><label class="wide">账号 / IP<input name="email" placeholder="邮箱关键字"></label><label>精确 IP<input name="ip" placeholder="例如 1.1.1.1"></label><label>国家<input name="country" maxlength="2" placeholder="US"></label><label class="wide">User-Agent<input name="user_agent" placeholder="客户端关键字"></label><label>最低欺诈分<select name="min_fraud_score"><option value="">全部</option><option value="60">60 以上</option><option value="70">70 以上</option><option value="85">85 以上</option></select></label><label>来源<select name="proxy_only"><option value="">全部来源</option><option value="1">仅代理 / 机房</option></select></label><label>伪装<select name="masked_only"><option value="">全部请求</option><option value="1">仅已伪装</option></select></label><button class="button primary" type="submit">应用筛选</button><button id="reset" class="button" type="button">重置</button>
    </form>
    <section id="summary" class="summary"></section>
    <section class="workspace"><section class="panel"><div class="panel-head"><div><h2>订阅泄露风险榜</h2><p>点击任意榜单数据，右侧查看全部关联账号</p></div><select id="ranking-sort" class="button"><option value="risk_users">综合风险</option><option value="short_term_spread">短时扩散</option><option value="proxy_users">代理来源</option><option value="cross_region_users">跨地区切换</option></select></div><nav id="tabs" class="tabs"></nav><div id="ranking-state" class="state">正在加载榜单...</div><div class="table-wrap"><table id="ranking-table" class="ranking-table" hidden><thead></thead><tbody></tbody></table></div><div class="pager"><button id="ranking-prev" class="button" type="button">上一页</button><span id="ranking-page"></span><button id="ranking-next" class="button" type="button">下一页</button></div></section><aside class="panel detail"><div class="panel-head"><div><h2>关联账号</h2><p>当前榜单数据关联的全部账号</p></div></div><div id="evidence" class="detail-body"><p class="muted">选择一条榜单数据后，这里会显示关联账号。</p></div></aside></section>
    <section class="panel raw"><div class="panel-head"><div><h2>原始访问记录</h2><p>所有记录均继承当前筛选条件</p></div></div><div id="raw-state" class="state">正在加载记录...</div><div class="table-wrap"><table id="logs" class="logs" hidden><thead><tr><th>时间</th><th>账号</th><th>IP / 地理位置</th><th>网络风险</th><th>User-Agent</th><th>规则结果</th></tr></thead><tbody></tbody></table></div><div class="pager"><button id="prev" class="button" type="button">上一页</button><span id="page"></span><button id="next" class="button" type="button">下一页</button></div></section>
</main>
<script>
const form=document.querySelector('#filters'),summary=document.querySelector('#summary'),tabs=document.querySelector('#tabs'),rankingTable=document.querySelector('#ranking-table'),rankingState=document.querySelector('#ranking-state'),evidence=document.querySelector('#evidence'),rawState=document.querySelector('#raw-state'),logs=document.querySelector('#logs'),logBody=logs.querySelector('tbody'),pageText=document.querySelector('#page'),prev=document.querySelector('#prev'),next=document.querySelector('#next'),dataUrl='{{ $analysisBaseUrl }}/data',logoutUrl='{{ $analysisBaseUrl }}/logout';
let payload=null,currentTab='risk_users',page=1,total=0,pageSize=10,rankingPage=1,rankingPageSize=10,selectedRankingIndex=null;
const tabMeta={risk_users:['风险总榜','账号综合泄露风险'],short_term_spread:['短时扩散榜','1 小时内新增多个来源 IP'],shared_ips:['高关联 IP 榜','一个 IP 同时使用多个账号'],proxy_users:['代理来源榜','代理、VPN、机房来源账号'],shared_user_agents:['共享 User-Agent 榜','同一客户端特征关联多个账号'],cross_region_users:['跨地区切换榜','短时间从多个地区访问同一账号'],high_frequency_users:['异常高频访问榜','短时间请求突增的账号'],rule_hits:['命中规则榜','查看伪装规则的触发分布']};
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const formatDate=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'-';
const initials=email=>String(email||'?').slice(0,2).toUpperCase();
function renderSummary(data){const items=[['suspected_leaks','疑似泄露账号','重点核查对象'],['distinct_ips','来源 IP 数','当前筛选范围'],['shared_ip_count','多账号关联 IP','重点证据线索'],['short_term_spread_count','短时扩散事件','1 小时窗口'],['high_risk_requests','高风险请求','欺诈分 ≥ 70']];summary.innerHTML=items.map(([key,label,note])=>'<div class="metric"><span>'+label+'</span><b>'+escapeHtml(data[key]??0)+'</b><small>'+note+'</small></div>').join('')}
function renderTabs(){tabs.innerHTML=Object.entries(tabMeta).map(([key,[label]])=>'<button type="button" class="tab '+(key===currentTab?'active':'')+'" data-tab="'+key+'">'+label+'</button>').join('')}
function rankingRows(){return payload?.rankings?.[currentTab]||[]}
function accountCells(accounts){return accounts?.map(account=>'<div class="account"><span class="avatar">'+escapeHtml(initials(account.email))+'</span><span><b>'+escapeHtml(account.email)+'</b><small>用户 ID #'+account.user_id+'</small></span></div>').join('')||''}
function renderRanking(){const rows=rankingRows(),pages=Math.max(1,Math.ceil(rows.length/rankingPageSize));rankingPage=Math.min(rankingPage,pages);const start=(rankingPage-1)*rankingPageSize,visible=rows.slice(start,start+rankingPageSize);rankingState.hidden=visible.length>0;rankingState.textContent=visible.length?'':'当前筛选范围暂无数据';rankingTable.hidden=!visible.length;let headers,html;
    if(currentTab==='risk_users'){headers=['#','账号','风险','陌生 IP','关联证据','最近异常'];html=visible.map((row,i)=>'<tr data-ranking-index="'+(start+i)+'"><td>'+String(start+i+1).padStart(2,'0')+'</td><td>'+accountCells([row.accounts?.[0]||row])+'</td><td><span class="risk '+(row.risk_score>=70?'high':row.risk_score>=40?'medium':'low')+'">'+row.risk_score+'</span><div class="risk-bar"><i style="width:'+row.risk_score+'%"></i></div></td><td>'+row.distinct_ips+'</td><td><span class="chip">'+escapeHtml((row.signals||[]).map(signal=>signal.label+' '+signal.count).join(' · '))+'</span></td><td class="subtle">'+formatDate(row.last_seen_at)+'</td></tr>').join('')}
    else if(['proxy_users','cross_region_users','high_frequency_users'].includes(currentTab)){headers=['#','账号','核心指标','请求数','关联账号','最近异常'];html=visible.map((row,i)=>'<tr data-ranking-index="'+(start+i)+'"><td>'+String(start+i+1).padStart(2,'0')+'</td><td>'+accountCells([row.accounts?.[0]||row])+'</td><td>'+escapeHtml(row.proxy_ips??row.distinct_countries??row.request_count??0)+'</td><td>'+escapeHtml(row.proxy_requests??row.request_count??0)+'</td><td>'+row.accounts?.length+'</td><td class="subtle">'+formatDate(row.last_seen_at)+'</td></tr>').join('')}
    else if(currentTab==='shared_ips'){headers=['#','IP','请求数','关联账号','地区数','最高风险'];html=visible.map((row,i)=>'<tr data-ranking-index="'+(start+i)+'"><td>'+String(start+i+1).padStart(2,'0')+'</td><td><b>'+escapeHtml(row.ip)+'</b><small class="subtle">'+(row.is_proxy?'代理/机房来源':'普通网络')+'</small></td><td>'+row.request_count+'</td><td>'+row.accounts.length+'</td><td>'+row.country_count+'</td><td>'+row.max_fraud_score+'</td></tr>').join('')}
    else if(currentTab==='shared_user_agents'){headers=['#','User-Agent','请求数','关联账号','关联 IP','最近访问'];html=visible.map((row,i)=>'<tr data-ranking-index="'+(start+i)+'"><td>'+String(start+i+1).padStart(2,'0')+'</td><td class="ua"><b>'+escapeHtml(row.user_agent)+'</b></td><td>'+row.request_count+'</td><td>'+row.accounts.length+'</td><td>'+row.distinct_ips+'</td><td class="subtle">'+formatDate(row.latest_seen_at)+'</td></tr>').join('')}
    else if(currentTab==='short_term_spread'){headers=['#','账号','新增 IP','窗口请求','窗口开始','窗口结束'];html=visible.map((row,i)=>'<tr data-ranking-index="'+(start+i)+'"><td>'+String(start+i+1).padStart(2,'0')+'</td><td>'+accountCells([row.accounts?.[0]||row])+'</td><td class="risk high">'+row.spread_ip_count+'</td><td>'+row.request_count+'</td><td>'+formatDate(row.window_start)+'</td><td>'+formatDate(row.window_end)+'</td></tr>').join('')}
    else{headers=['#','规则','请求数','关联账号','最近触发'];html=visible.map((row,i)=>'<tr data-ranking-index="'+(start+i)+'"><td>'+String(start+i+1).padStart(2,'0')+'</td><td><b>'+escapeHtml(row.reason)+'</b></td><td>'+row.request_count+'</td><td>'+row.accounts.length+'</td><td class="subtle">'+formatDate(row.latest_seen_at)+'</td></tr>').join('')}
    rankingTable.querySelector('thead').innerHTML='<tr>'+headers.map(header=>'<th>'+header+'</th>').join('')+'</tr>';rankingTable.querySelector('tbody').innerHTML=html;document.querySelector('#ranking-page').textContent='第 '+rankingPage+' 页 / 共 '+pages+' 页';document.querySelector('#ranking-prev').disabled=rankingPage<=1;document.querySelector('#ranking-next').disabled=rankingPage>=pages;if(selectedRankingIndex!==null){rankingTable.querySelector('tbody tr[data-ranking-index="'+selectedRankingIndex+'"]')?.classList.add('selected')}}
function renderEvidence(){const row=selectedRankingIndex===null?null:rankingRows()[selectedRankingIndex];if(!row){evidence.innerHTML='<p class="muted">选择一条榜单数据后，这里会显示关联账号。</p>';return}const accounts=row.accounts||[];const title=row.ip||row.user_agent||row.reason||row.email||'当前线索';evidence.innerHTML='<div class="case-title"><div><h3>'+escapeHtml(title)+'</h3><p>'+escapeHtml(tabMeta[currentTab][1])+' · 关联 '+accounts.length+' 个账号</p></div></div><div class="detail-section"><div class="section-title">关联账号 <span>'+accounts.length+' 个</span></div><div class="linked-list">'+(accounts.length?accounts.map(account=>'<div class="linked-account"><b>'+escapeHtml(account.email)+'</b><small>用户 ID #'+account.user_id+' · 请求 '+account.request_count+' 次 · '+account.distinct_ips+' 个 IP · '+account.distinct_countries+' 个地区 · 代理请求 '+account.proxy_requests+' 次 · 最高欺诈分 '+account.max_fraud_score+'</small><small>首次 '+formatDate(account.first_seen_at)+' · 最近 '+formatDate(account.last_seen_at)+'</small></div>').join(''):'<p class="muted">没有关联账号。</p>')+'</div></div><div class="notice">该榜单只表示访问特征存在关联，需结合账号常用 IP 和实际使用情况进一步核查。</div>'}
function renderLogs(data){logBody.innerHTML=(data.data||[]).map(row=>'<tr><td>'+formatDate(row.created_at)+'</td><td>'+escapeHtml(row.email)+'<br><span class="subtle">#'+row.user_id+'</span></td><td>'+escapeHtml(row.ip||'-')+'<br><span class="subtle">'+escapeHtml([row.country_code,row.country,row.city].filter(Boolean).join(' · '))+'</span></td><td>'+(row.is_proxy?'<span class="badge red">代理</span> ':'')+(row.fraud_score>=70?'<span class="badge red">'+row.fraud_score+'</span>':escapeHtml(row.fraud_score??'-'))+'</td><td class="ua">'+escapeHtml(row.user_agent||'-')+'</td><td>'+(row.masked?'<span class="badge">已伪装</span>':'原始域名')+(row.reason?'<br><span class="subtle">'+escapeHtml(row.reason)+'</span>':'')+'</td></tr>').join('');total=data.total;page=data.page;pageText.textContent='第 '+page+' 页 / 共 '+Math.max(1,Math.ceil(total/pageSize))+' 页';prev.disabled=page<=1;next.disabled=page*pageSize>=total;rawState.hidden=!!data.data.length;logs.hidden=!data.data.length}
async function load(){const query=new URLSearchParams(new FormData(form));query.set('page',page);query.set('page_size',pageSize);rankingState.hidden=false;rankingState.textContent='正在加载榜单...';rawState.hidden=false;rawState.textContent='正在加载记录...';try{const response=await fetch(dataUrl+'?'+query,{credentials:'include'});if(response.status===401){location.href='{{ $analysisBaseUrl }}';return}const result=await response.json();if(!response.ok)throw new Error(result.message||'加载失败');payload=result;renderSummary(result.summary);renderTabs();renderRanking();renderEvidence();renderLogs(result.logs)}catch(error){rankingState.hidden=false;rankingState.textContent=error.message||'榜单加载失败';rawState.hidden=false;rawState.textContent=error.message||'记录加载失败';logs.hidden=true}}
form.addEventListener('submit',event=>{event.preventDefault();page=1;rankingPage=1;selectedRankingIndex=null;load()});document.querySelector('#reset').addEventListener('click',()=>{form.reset();page=1;rankingPage=1;selectedRankingIndex=null;load()});document.querySelector('#refresh').addEventListener('click',()=>load());document.querySelector('#ranking-sort').addEventListener('change',event=>{currentTab=event.target.value;rankingPage=1;selectedRankingIndex=null;renderTabs();renderRanking();renderEvidence()});tabs.addEventListener('click',event=>{const button=event.target.closest('[data-tab]');if(!button)return;currentTab=button.dataset.tab;rankingPage=1;selectedRankingIndex=null;document.querySelector('#ranking-sort').value=['risk_users','short_term_spread','proxy_users','cross_region_users'].includes(currentTab)?currentTab:'risk_users';renderTabs();renderRanking();renderEvidence()});rankingTable.addEventListener('click',event=>{const row=event.target.closest('[data-ranking-index]');if(!row)return;selectedRankingIndex=Number(row.dataset.rankingIndex);renderRanking();renderEvidence()});document.querySelector('#ranking-prev').addEventListener('click',()=>{if(rankingPage>1){rankingPage--;selectedRankingIndex=null;renderRanking();renderEvidence()}});document.querySelector('#ranking-next').addEventListener('click',()=>{const pages=Math.max(1,Math.ceil(rankingRows().length/rankingPageSize));if(rankingPage<pages){rankingPage++;selectedRankingIndex=null;renderRanking();renderEvidence()}});prev.addEventListener('click',()=>{if(page>1){page--;load()}});next.addEventListener('click',()=>{if(page*pageSize<total){page++;load()}});document.querySelector('#logout').addEventListener('click',async()=>{await fetch(logoutUrl,{method:'POST',credentials:'include'});location.reload()});load();
</script>
</body>
</html>
